<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#ffc928"><link rel="manifest" href="manifest.json"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/responsive.css"><link rel="apple-touch-icon" href="assets/icons/icon-192.svg"><title>Cart</title></head><body><main class="app"><div id="top"></div><div id="items"></div><div class="summary" id="summary"></div><input class="field" id="coupon" placeholder="Coupon code"><button class="primary" id="checkout">Proceed to Checkout</button><div id="nav"></div></main><div class="toast"></div><div class="sheet" onclick="if(event.target===this)this.classList.remove('show')"><div><h2>Install this app on your iPhone</h2><p>1. Tap the Share button in Safari.<br><br>2. Select <b>Add to Home Screen</b>.<br><br>3. Tap <b>Add</b>.</p><button class="primary" onclick="this.closest('.sheet').classList.remove('show')">Got it</button></div></div><script src="js/products.js"></script><script src="js/app.js"></script><script src="js/cart.js"></script><script src="js/pwa.js"></script><script>$('#top').innerHTML=top('My Cart',true);$('#nav').innerHTML=nav('order');function draw(){let c=cart();$('#items').innerHTML=c.map((i,n)=>{let p=PRODUCTS.find(x=>x.id===i.id);return `<div class="cart-row"><img src="assets/images/${p.id}.svg"><div><b>${p.name}</b><div class="meta">${(i.extras||[]).join(', ')||'Standard'}</div><div class="price">$${(p.price*i.qty).toFixed(2)}</div><div class="qty"><button data-d="${n},-1">−</button><b>${i.qty}</b><button data-d="${n},1">+</button></div></div><button class="icon-btn" data-r="${n}">×</button></div>`}).join('')||'<div class="empty">Your cart is empty.</div>';let sub=c.reduce((s,i)=>s+PRODUCTS.find(p=>p.id===i.id).price*i.qty,0),fee=c.length?2.5:0,disc=0;$('#summary').innerHTML=`<p><span>Subtotal</span><b>$${sub.toFixed(2)}</b></p><p><span>Delivery Fee</span><b>$${fee.toFixed(2)}</b></p><p><span>Discount</span><b>-$${disc.toFixed(2)}</b></p><p class="total"><span>Total</span><span>$${(sub+fee-disc).toFixed(2)}</span></p>`;$$('[data-d]').forEach(b=>b.onclick=()=>{let [n,d]=b.dataset.d.split(',').map(Number),x=cart();x[n].qty+=d;if(x[n].qty<1)x.splice(n,1);store.set('cart',x);draw();renderBadges()});$$('[data-r]').forEach(b=>b.onclick=()=>{let x=cart();x.splice(+b.dataset.r,1);store.set('cart',x);draw();renderBadges()})}$('#coupon').onchange=()=>toast($('#coupon').value.toUpperCase()==='FOOD10'?'Coupon applied':'Coupon saved for checkout');$('#checkout').onclick=()=>cart().length?location.href='checkout.html':toast('Your cart is empty');draw();renderBadges();</script></body></html>